export interface Zone {
  id: string;
  /** "HH:MM", UTC. */
  opens: string;
  /** "HH:MM", UTC. */
  closes: string;
  express: boolean;
}

export interface Order {
  id: string;
  weightKg: number;
  /** How many times the delivery slot has been changed. */
  slotChanges: number;
  /** The start of the delivery slot as an ISO time in UTC; null until one is chosen. */
  slot: string | null;
  /** The pickup time as an ISO time in UTC; null until one is chosen. */
  pickup: string | null;
  /** Since 4.0 the address carries its zone whole. */
  address: { line: string; zone: Zone };
}

export interface Transport {
  get(path: string): Promise<unknown>;
  put(path: string, body: unknown): Promise<unknown>;
}

export interface Client {
  getOrder(id: string): Promise<Order>;
  /** For callers that hold a zone's id and no order. Rejects when the zone service does not answer. */
  getZone(id: string): Promise<Zone>;
  setPickup(id: string, time: string): Promise<unknown>;
  setSlot(id: string, slot: string): Promise<unknown>;
}

export function createClient(transport: Transport): Client;
